 $p=json_decode(base64_decode($argv[3]),true,16,JSON_THROW_ON_ERROR);$receipt=(int)$argv[4];$s=$db->prepare("SELECT j.public_reference FROM delivery_receipts r JOIN delivery_jobs j ON j.id=r.delivery_id WHERE r.id=? AND j.public_reference LIKE 'LAB-CASH11-RACE-%'");$s->execute([$receipt]);if(!$s->fetchColumn())exit(2);
