 $original=$db->query("SELECT * FROM delivery_jobs WHERE source='hambelela' ORDER BY id LIMIT 1")->fetch();unset($original['id'],$original['active_primary_order_id']);$original['public_reference']=$marker;$original['additional_delivery']=1;$original['additional_delivery_reason']='Isolated cash concurrency regression';$original['driver_employee_id']=$driver;$original['status']='out_for_delivery';$db->prepare('INSERT INTO delivery_jobs (`'.implode('`,`',array_keys($original)).'`) VALUES('.implode(',',array_fill(0,count($original),'?')).')')->execute(array_values($original));$job=(int)$db->lastInsertId();
