 $p=['action'=>'submit','key'=>keyRace(),'currency'=>'NAD','allocations'=>[['receipt_id'=>$receipt,'minor'=>10001]],'declared_minor'=>10001,'note'=>'','attested'=>true];$keys[]=$p['key'];$out=race11($driver,$p,$p,$receipt);if(!$out[0]['ok']||!$out[1]['ok']||$out[0]['result']['id']!==$out[1]['result']['id'])throw new RuntimeException('Same-key race failed');echo "PASS concurrent driver retries return one handover\n";$handover=$out[0]['result']['id'];
