}finally{
 $s=$db->prepare('SELECT id FROM ops_employees WHERE id=? AND full_name=?');$s->execute([$driver,$marker]);if(!$s->fetchColumn())throw new RuntimeException('Cleanup target changed');$db->beginTransaction();
 $s=$db->prepare('SELECT id FROM delivery_cash_handovers WHERE driver_id=?');$s->execute([$driver]);foreach($s->fetchAll(PDO::FETCH_COLUMN) as $id){$q=$db->prepare("SELECT id FROM notifications WHERE related_type='delivery_cash_handover' AND related_id=?");$q->execute([$id]);foreach($q->fetchAll(PDO::FETCH_COLUMN) as $n){$db->prepare('DELETE FROM notification_recipients WHERE notification_id=?')->execute([$n]);$db->prepare('DELETE FROM notifications WHERE id=?')->execute([$n]);}$db->prepare('DELETE FROM delivery_cash_audit WHERE handover_id=?')->execute([$id]);$db->prepare('DELETE FROM delivery_cash_allocations WHERE handover_id=?')->execute([$id]);$db->prepare('DELETE FROM delivery_cash_handovers WHERE id=? AND driver_id=?')->execute([$id,$driver]);}
 foreach($keys as $key)$db->prepare("DELETE FROM delivery_requests WHERE request_uuid=? AND actor_key IN(?, 'cash:2')")->execute([$key,'cash:'.$driver]);$db->prepare('DELETE FROM delivery_events WHERE delivery_id=?')->execute([$job]);$db->prepare('DELETE FROM delivery_receipts WHERE delivery_id=? AND collected_by_employee_id=?')->execute([$job,$driver]);$db->prepare('DELETE FROM delivery_jobs WHERE id=? AND public_reference=?')->execute([$job,$marker]);$db->prepare('DELETE FROM delivery_driver_profiles WHERE employee_id=?')->execute([$driver]);$db->prepare('DELETE FROM ops_employees WHERE id=? AND full_name=?')->execute([$driver,$marker]);$db->commit();echo "PASS exact synthetic race fixtures removed; existing data preserved\n";
